/**
 * Wallets written by the published @vaultys/id 3.0.4, frozen for the 4.0 implementations (TypeScript and Go).
 *
 * 3.x handshakes are not deterministic (random nonces and timestamps), so these vectors are generated once and
 * committed, not regenerated by the tests: `pnpm test:legacy:vectors` overwrites them with new random wallets.
 *
 * Each wallet carries the store exactly as 3.x serialized it (`store`, read by TypeScript) and the same data
 * extracted for the other languages: `entropy` and the v0 certificates the store holds.
 */
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { Buffer } from "buffer/";
import * as v3 from "@vaultys/id_3";

type Alg = "ed25519" | "dilithium_ed25519" | "dilithium";
type V3Manager = InstanceType<typeof v3.IdManager>;

const newWallet = async (type: number, alg: Alg) =>
  new v3.IdManager(
    await v3.VaultysId.fromEntropy(Buffer.from(v3.crypto.randomBytes(32)) as never, type, alg),
    v3.MemoryStorage(() => {}),
  );

const connect = async (a: V3Manager, b: V3Manager) => {
  const channel = v3.MemoryChannel.createBidirectionnal();
  await Promise.all([a.askContact(channel), b.acceptContact(channel.otherend!)]);
};

const hex = (b: Uint8Array) => Buffer.from(b).toString("hex");

const certificatesOf = (m: V3Manager) => {
  const raw = JSON.parse(m.store.toString());
  const out: string[] = [];
  const bytes = (v: unknown) => (typeof v === "string" && v.startsWith("_bx_") ? Buffer.from(v.slice(4), "base64") : null);
  for (const table of ["!contacts", "!registrations"]) {
    for (const entry of Object.values((raw[table] ?? {}) as Record<string, { certificate?: string }>)) {
      const c = bytes(entry?.certificate);
      if (c) out.push(hex(c));
    }
  }
  for (const value of Object.values((raw["!wot"] ?? {}) as Record<string, string>)) {
    const c = bytes(value);
    if (c) out.push(hex(c));
  }
  return [...new Set(out)];
};

const describeWallet = (name: string, m: V3Manager, created: { type: number; alg: Alg }) => ({
  name,
  created,
  did: m.vaultysId.did,
  id: hex(m.vaultysId.id),
  entropy: hex(m.vaultysId.keyManager.entropy as Uint8Array),
  store: m.store.toString(),
  certificates: certificatesOf(m),
});

export async function buildVectors() {
  const alice = await newWallet(1, "ed25519");
  const bob = await newWallet(1, "ed25519");
  const carol = await newWallet(1, "dilithium_ed25519");
  const dave = await newWallet(0, "ed25519");
  const lonely = await newWallet(1, "dilithium_ed25519");
  await connect(alice, bob);
  await connect(alice, carol);
  await connect(dave, alice);

  // what 3.x made of a store without certificates after a restart (IdManager.fromStore)
  const lonelyReopened = await v3.IdManager.fromStore(v3.MemoryStorage(() => {}).fromString(lonely.store.toString()));

  const tampered = Buffer.from(certificatesOf(alice)[0], "hex");
  tampered[tampered.length - 1] ^= 1;

  const plaintext = "message chiffré par la 3.x";
  const dhies = await alice.vaultysId.dhiesEncrypt(plaintext, bob.vaultysId.id);

  return {
    description: "Wallets written by @vaultys/id 3.0.4 (stores, v0 certificates, DHIES v1), frozen for the 4.0 implementations",
    generator: "typescript/test/interops/generate-legacy-v3-vectors.ts",
    library: "@vaultys/id@3.0.4",
    wallets: [describeWallet("alice", alice, { type: 1, alg: "ed25519" }), describeWallet("bob", bob, { type: 1, alg: "ed25519" }), describeWallet("carol", carol, { type: 1, alg: "dilithium_ed25519" }), describeWallet("dave", dave, { type: 0, alg: "ed25519" }), describeWallet("lonely", lonely, { type: 1, alg: "dilithium_ed25519" })],
    /** the identity 3.x itself reopened `lonely` as (a machine ed25519) */
    lonelyReopenedDid: lonelyReopened.vaultysId.did,
    /** a certificate of alice's with its last byte flipped: must not verify */
    tamperedCertificate: hex(tampered),
    dhiesV1: { from: "alice", to: "bob", senderId: hex(alice.vaultysId.id), message: hex(dhies!), plaintext },
  };
}

export const VECTORS_PATH = join(__dirname, "legacy-v3-vectors.json");
/** Copy read by the Go tests. */
export const VECTOR_COPIES = [join(__dirname, "../../../go/pkg/legacyv3/testdata/legacy-v3-vectors.json")];

if (require.main === module) {
  buildVectors().then((vectors) => {
    const text = JSON.stringify(vectors, null, 2) + "\n";
    for (const path of [VECTORS_PATH, ...VECTOR_COPIES]) writeFileSync(path, text);
    console.log(`wrote ${VECTORS_PATH}: ${vectors.wallets.length} wallets`);
  });
}
